            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "In sum, my contact lenses had made me fifteen years old again. That is: festering, self-crucified bundle of doubt, horror, and absolute imperfection. The worst age in all one's life had returned to haunt me with its pimpled, bumpy ghost.", Author = "Ray Bradbury" },
